<script setup>
import { Head } from '@inertiajs/vue3';
import { computed, onBeforeUnmount, ref } from 'vue';
const props=defineProps({code:String});
const displayName=ref(''), joined=ref(false), cameraOn=ref(false), micOn=ref(false), recording=ref(false), elapsed=ref(0), copied=ref(false), camera=ref(null), error=ref(''), stream=ref(null), recorder=ref(null);
const chunks=[]; let tick;
const inviteLink=computed(()=>window.location.href);
const formattedTime=computed(()=>[Math.floor(elapsed.value/3600),Math.floor((elapsed.value%3600)/60),elapsed.value%60].map(v=>String(v).padStart(2,'0')).join(':'));
const joinRoom=()=>{if(!displayName.value.trim())return;joined.value=true;tick=setInterval(()=>elapsed.value++,1000);};
const toggleCamera=async()=>{try{if(!stream.value)stream.value=await navigator.mediaDevices.getUserMedia({video:true,audio:true});cameraOn.value=!cameraOn.value;stream.value.getVideoTracks().forEach(t=>t.enabled=cameraOn.value);micOn.value=true;stream.value.getAudioTracks().forEach(t=>t.enabled=true);if(camera.value)camera.value.srcObject=stream.value;error.value='';}catch{error.value='Camera/microphone permission is not available. Allow browser access and try again.';}};
const toggleMic=async()=>{try{if(!stream.value)stream.value=await navigator.mediaDevices.getUserMedia({video:true,audio:true});micOn.value=!micOn.value;stream.value.getAudioTracks().forEach(t=>t.enabled=micOn.value);if(camera.value)camera.value.srcObject=stream.value;error.value='';}catch{error.value='Microphone permission is not available. Allow browser access and try again.';}};
const copyLink=async()=>{await navigator.clipboard.writeText(inviteLink.value);copied.value=true;setTimeout(()=>copied.value=false,1800);};
const startRecording=async()=>{if(!window.confirm("Confirm everyone in the meeting has agreed to recording. This saves a local browser recording."))return;try{if(!stream.value)stream.value=await navigator.mediaDevices.getUserMedia({video:true,audio:true});recorder.value=new MediaRecorder(stream.value);chunks.length=0;recorder.value.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.value.onstop=()=>{const file=new Blob(chunks,{type:recorder.value.mimeType||'video/webm'});const url=URL.createObjectURL(file);const a=document.createElement('a');a.href=url;a.download='meetly-'+props.code+'.webm';a.click();URL.revokeObjectURL(url);};recorder.value.start();recording.value=true;}catch{error.value='Turn on camera and microphone before recording.';}};
const stopRecording=()=>{recorder.value?.stop();recording.value=false;};
const leaveRoom=()=>{if(recorder.value?.state==='recording')stopRecording();stream.value?.getTracks().forEach(t=>t.stop());window.location.href=route('dashboard');};
onBeforeUnmount(()=>{clearInterval(tick);stream.value?.getTracks().forEach(t=>t.stop());});
</script>
<template>
<Head title="Meeting room"/><div class="min-h-screen bg-slate-950 text-white">
<header class="flex flex-wrap items-center justify-between gap-3 border-b border-white/10 px-4 py-4 sm:px-7"><a :href="route('dashboard')" class="flex items-center gap-3"><span class="grid h-9 w-9 place-items-center rounded-xl bg-indigo-500 font-bold">m</span><span class="font-semibold">meetly</span></a><div class="flex items-center gap-3 text-sm"><span class="rounded-lg bg-white/10 px-3 py-2 font-mono">{{formattedTime}}</span><span class="rounded-full bg-emerald-400/10 px-3 py-1.5 text-emerald-300">Room {{code}}</span></div></header>
<main class="mx-auto grid max-w-7xl gap-5 px-4 py-6 lg:grid-cols-[minmax(0,1fr)_300px]"><section class="space-y-4">
<div v-if="!joined" class="mx-auto mt-10 max-w-md rounded-3xl border border-white/10 bg-white/5 p-7 text-center"><div class="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-indigo-500/20 text-2xl">▣</div><h1 class="mt-5 text-2xl font-bold">Join this meeting</h1><p class="mt-2 text-sm text-slate-400">Anyone with this invitation link can enter a display name and join this room.</p><form class="mt-6 space-y-3" @submit.prevent="joinRoom"><input v-model="displayName" required maxlength="60" placeholder="Your display name" class="w-full rounded-xl border-white/10 bg-slate-900 text-white placeholder:text-slate-500 focus:border-indigo-400 focus:ring-indigo-400"/><button class="w-full rounded-xl bg-indigo-500 px-4 py-3 font-semibold hover:bg-indigo-400">Join meeting</button></form></div>
<template v-else><div class="relative grid min-h-[55vh] place-items-center overflow-hidden rounded-3xl border border-white/10 bg-slate-900"><video ref="camera" autoplay muted playsinline class="h-full max-h-[68vh] w-full object-cover" :class="cameraOn?'':'hidden'"></video><div v-if="!cameraOn" class="text-center"><div class="mx-auto grid h-24 w-24 place-items-center rounded-full bg-indigo-500 text-3xl font-bold">{{displayName.slice(0,1).toUpperCase()}}</div><p class="mt-4 font-medium">{{displayName}} · Camera off</p></div><span class="absolute bottom-4 left-4 rounded-lg bg-black/50 px-3 py-2 text-sm">{{displayName}} <span v-if="!micOn">· Muted</span></span></div><div class="flex flex-wrap items-center justify-center gap-3"><button @click="toggleMic" class="rounded-xl px-5 py-3 text-sm font-semibold" :class="micOn?'bg-white/10 hover:bg-white/20':'bg-rose-600 hover:bg-rose-500'">{{micOn?'🎙 Mute':'🔇 Unmute'}}</button><button @click="toggleCamera" class="rounded-xl px-5 py-3 text-sm font-semibold" :class="cameraOn?'bg-white/10 hover:bg-white/20':'bg-rose-600 hover:bg-rose-500'">{{cameraOn?'▣ Camera off':'▧ Camera on'}}</button><button @click="recording?stopRecording():startRecording()" class="rounded-xl px-5 py-3 text-sm font-semibold" :class="recording?'bg-rose-600':'bg-white/10 hover:bg-white/20'">{{recording?'■ Stop recording':'● Record'}}</button><button @click="leaveRoom" class="rounded-xl bg-rose-600 px-5 py-3 text-sm font-semibold hover:bg-rose-500">Leave</button></div></template><p v-if="error" class="rounded-xl bg-rose-500/10 p-3 text-sm text-rose-300">{{error}}</p>
</section><aside class="space-y-4"><section class="rounded-2xl border border-white/10 bg-white/5 p-5"><h2 class="font-semibold">Invite people</h2><p class="mt-2 text-sm leading-6 text-slate-400">Share this link. Anyone who opens it can enter with a display name.</p><div class="mt-4 flex gap-2"><input readonly :value="inviteLink" class="min-w-0 flex-1 rounded-lg border-white/10 bg-slate-900 text-xs text-slate-300"/><button @click="copyLink" class="rounded-lg bg-indigo-500 px-3 text-xs font-semibold">{{copied?'Copied':'Copy'}}</button></div></section><section class="rounded-2xl border border-white/10 bg-white/5 p-5"><div class="flex items-center justify-between"><h2 class="font-semibold">Participants</h2><span class="rounded-full bg-white/10 px-2 py-1 text-xs">{{joined?'1':'0'}}</span></div><p class="mt-3 text-sm text-slate-400">{{joined?displayName:'Share the link to invite people.'}}</p><p class="mt-4 border-t border-white/10 pt-4 text-xs leading-5 text-amber-200/80">Local preview mode: LiveKit is not configured, so remote participants cannot see or hear each other yet.</p></section><section class="rounded-2xl border border-white/10 bg-white/5 p-5"><h2 class="font-semibold">Recording</h2><p class="mt-2 text-sm leading-6 text-slate-400">Browser recording downloads your local camera/microphone as WebM. Cloud recording is not enabled.</p></section></aside></main></div>
</template>

